  'Yearly bands for one part, in XAF, in force since {a}. Each month the taxable income less the contributions taken before tax is multiplied by 12, less the professional deduction, divided by the household\'s parts (1, plus 1 for a spouse and ½ per child in charge), taxed on these bands, multiplied back by the parts and divided by 12.': 'Tranches annuelles pour une part, en XAF, en vigueur depuis le {a}. Chaque mois, le revenu imposable moins les cotisations déduites avant impôt est multiplié par 12, diminué de l\'abattement professionnel, divisé par les parts du foyer (1, plus 1 pour le conjoint et ½ par enfant à charge), taxé sur ces tranches, remultiplié par les parts et divisé par 12.',
  'Yearly bands in XAF, in force since {a}. Each month the taxable income less the contributions taken before tax is multiplied by 12, less the professional deduction and the yearly allowance, taxed on these bands and divided by 12. No tax below the monthly threshold.': 'Tranches annuelles en XAF, en vigueur depuis le {a}. Chaque mois, le revenu imposable moins les cotisations déduites avant impôt est multiplié par 12, diminué de l\'abattement professionnel et de l\'abattement annuel, taxé sur ces tranches et divisé par 12. Pas d\'impôt sous le seuil mensuel.',
