  ") apply automatically. Add an item here to give this employee a different amount, an extra allowance, or to exclude one.": ") s'appliquent automatiquement. Ajoutez un élément ici pour donner à cet employé un autre montant, une indemnité en plus, ou pour en exclure une.",
  ") no longer matches its hash: it, or an entry before it, was changed directly in the database. Keep a copy of the database as it is and find out who had access.": ") ne correspond plus à son empreinte : elle, ou une entrée avant elle, a été modifiée directement dans la base. Gardez une copie de la base en l'état et cherchez qui y avait accès.",
  "). You can end your day from there.": "). Vous pouvez terminer votre journée depuis là-bas.",
  ", IPR-free up to {a}% of basic": ", exonéré d'IPR jusqu'à {a} % de la base",
