  ", × months under contract ÷ 12": ", × mois sous contrat ÷ 12",
  ". A vacant unit's people report to the nearest head above it. Cellules (staff units) are shown with a dashed border.": ". Les personnes d'une unité vacante rendent compte au chef le plus proche au-dessus. Les cellules (unités d'état-major) sont affichées avec une bordure en pointillés.",
  ". Asked by": ". Demandée par",
  ". Check the document before the leave counts.": ". Vérifiez le document avant que le congé compte.",
  ". Each month the taxable income is multiplied by 12, taxed on these bands and divided by 12; then the reduction per dependant and the cap apply.": ". Chaque mois, le revenu imposable est multiplié par 12, imposé sur ces tranches et divisé par 12 ; puis la réduction par personne à charge et le plafond s'appliquent.",
  ". Every page you open is shown to the company.": ". Chaque page que vous ouvrez est montrée à l'entreprise.",
  ". IPR withheld:": ". IPR retenu :",
  ". It is added to the payslip of the pay month.": ". Il est ajouté au bulletin du mois de paie.",
  ". Recorded by": ". Enregistrée par",
