  "51 to 300 employees": "De 51 à 300 employés",
  ": every module, up to 50 employees and one company.": " : tous les modules, jusqu'à 50 employés et une entreprise.",
  ": suspended": " : suspendue",
  ": unpaid invoice": " : facture impayée",
  "A correction fixes the current unit without adding a line to the history.": "Une correction rectifie l'unité actuelle sans ajouter de ligne à l'historique.",
  "A holiday moved inside a closed month changes that month's basic pay. The difference is added to the payroll shown; calculate it again to include it.": "Un jour férié déplacé dans un mois clôturé change le salaire de base de ce mois. La différence est ajoutée à la paie indiquée ; recalculez-la pour l'inclure.",
  "A month": "Par mois",
  "A new amount applies from its date; earlier amounts stay in the history.": "Un nouveau montant s'applique à partir de sa date ; les montants précédents restent dans l'historique.",
  "A new code was sent to {a}.": "Un nouveau code a été envoyé à {a}.",
  "A ruled table with element codes and separate employee and employer columns, as accountants like it.": "Un tableau réglé avec les codes des éléments et des colonnes salarié et employeur séparées, comme les comptables l'aiment.",
  "A shared office computer lets employees without a smartphone check in. The network check still applies.": "Un ordinateur partagé du bureau permet aux employés sans smartphone de pointer. Le contrôle du réseau s'applique toujours.",
  "A unit sits under a unit of a higher level (smaller number); levels can be skipped. Staff units, such as a Cellule, can sit anywhere.": "Une unité se place sous une unité de niveau supérieur (numéro plus petit) ; des niveaux peuvent être sautés. Les unités d'état-major, comme une Cellule, peuvent se placer n'importe où.",
