  "After someone leaves (account disabled, last contract ended), their personal data is kept for this long, then HR erases it here. Check the period with your lawyer.": "Après le départ d'une personne (compte désactivé, dernier contrat terminé), ses données personnelles sont gardées pendant cette durée, puis les RH les effacent ici. Vérifiez la durée avec votre avocat.",
