  "Code by email": "Code par e-mail",
  "Codes and notifications. Without an email server configured, emails are only kept here (\"LOGGED\"), which is how to read codes while testing.": "Codes et notifications. Sans serveur d'e-mail configuré, les e-mails sont seulement gardés ici (« LOGGED »), ce qui permet de lire les codes pendant les essais.",
  "Columns: code, name, level, parent, cost_centre, head_registration_no. Level and parent are codes. Commas or semicolons both work. Units are matched by code: new codes are created, existing ones updated. Nothing is saved if any line has a problem.": "Colonnes : code, name, level, parent, cost_centre, head_registration_no. Level et parent sont des codes. Virgules et points-virgules fonctionnent. Les unités sont reconnues par leur code : les nouveaux codes sont créés, les existants mis à jour. Rien n'est enregistré si une ligne pose problème.",
