  "The position a phone shares at check-in is erased after this many days; the check-in itself (time, site, method) stays. 0 keeps positions. Everyone sees this period in the": "La position qu'un téléphone partage au pointage est effacée après ce nombre de jours ; le pointage lui-même (heure, site, méthode) reste. 0 garde les positions. Chacun voit cette durée dans la",
