  "When the government moves a holiday, set its observed date. Attendance and payroll use the observed date only.": "Quand le gouvernement déplace un jour férié, indiquez sa date observée. Les présences et la paie n'utilisent que la date observée.",
  "When you need help, let your provider's support team look at your company's data, read-only, for a few days. They cannot change anything. Every page they open is listed here, and you can close the access at any time.": "Quand vous avez besoin d'aide, laissez l'équipe d'assistance de votre fournisseur consulter les données de votre entreprise, en lecture seule, pendant quelques jours. Elle ne peut rien modifier. Chaque page qu'elle ouvre est listée ici, et vous pouvez fermer l'accès à tout moment.",
