  "Year to date": "Cumul de l'année",
  "Yearly bands for one part, in XAF, in force since {a}. Each month the taxable income is multiplied by 12, less the professional deduction, divided by the household's parts (1, plus 1 for a spouse and ½ per child in charge), taxed on these bands, multiplied back by the parts and divided by 12.": "Tranches annuelles pour une part, en XAF, en vigueur depuis le {a}. Chaque mois, le revenu imposable est multiplié par 12, diminué de l'abattement professionnel, divisé par les parts du foyer (1, plus 1 pour un conjoint et ½ par enfant à charge), imposé sur ces tranches, remultiplié par les parts et divisé par 12.",
  "Years after leaving": "Années après le départ",
  "Yes": "Oui",
  "You are not assigned to a site yet. Contact HR.": "Vous n'êtes pas encore affecté à un site. Contactez les RH.",
  "You are on a support visit: your own account settings are in your own company.": "Vous êtes en visite d'assistance : les réglages de votre propre compte sont dans votre propre entreprise.",
  "You are on an approved mission (": "Vous êtes en mission approuvée (",
  "You can also add it later. HR checks it before the leave counts.": "Vous pouvez aussi l'ajouter plus tard. Les RH le vérifient avant que le congé compte.",
  "You do not have permission to do this.": "Vous n'avez pas l'autorisation de faire cela.",
  "You do not have permission to open this page.": "Vous n'avez pas l'autorisation d'ouvrir cette page.",
  "You see what its users see, read-only, until": "Vous voyez ce que voient ses utilisateurs, en lecture seule, jusqu'à",
  "You see your own data. The head of your unit (and the heads above) see your attendance and requests. HR sees everyone's file. Finance sees pay and payments. Every export and change is recorded in an audit log.": "Vous voyez vos propres données. Le chef de votre unité (et les chefs au-dessus) voient vos présences et vos demandes. Les RH voient le dossier de chacun. La finance voit la paie et les paiements. Chaque export et chaque modification est enregistré dans un journal d'audit.",
  "Your answer": "Votre réponse",
  "Your company has not allowed this Microsoft directory. Ask your administrator to set it on the Company page.": "Votre entreprise n'a pas autorisé cet annuaire Microsoft. Demandez à votre administrateur de l'indiquer sur la page Entreprise.",
  "Your company is not billed on this installation.": "Votre entreprise n'est pas facturée sur cette installation.",
  "Your data": "Vos données",
  "Your identity and contact details, your unit, contract, grade and salary.": "Votre identité et vos coordonnées, votre unité, votre contrat, votre grade et votre salaire.",
  "Your manager has scored you for": "Votre responsable vous a évalué pour",
  "Your password": "Votre mot de passe",
  "Your password alone will then open your account.": "Votre mot de passe seul ouvrira alors votre compte.",
  "Your password was set by an administrator. Choose your own to continue.": "Votre mot de passe a été défini par un administrateur. Choisissez le vôtre pour continuer.",
  "Your payslips, the payments made to you, and the amounts declared to CNSS, DGI, INPP and ONEM.": "Vos bulletins de paie, les paiements qui vous sont faits, et les montants déclarés à la CNSS, la DGI, l'INPP et l'ONEM.",
  "Your people can sign in with their work account, but only from your organization's own Microsoft directory. Find its tenant ID in the Microsoft Entra admin centre, under Overview. Their email in HR Pay must be their Microsoft sign-in name.": "Vos collaborateurs peuvent se connecter avec leur compte professionnel, mais seulement depuis l'annuaire Microsoft de votre organisation. Son ID de tenant se trouve dans le centre d'administration Microsoft Entra, sous Vue d'ensemble. Leur e-mail dans HR Pay doit être leur identifiant Microsoft.",
  "Your provider did not confirm this email address.": "Votre fournisseur n'a pas confirmé cette adresse e-mail.",
  "Your provider has not given payment details yet.": "Votre fournisseur n'a pas encore donné ses coordonnées de paiement.",
  "Your provider sends a .licence file. It is checked here, without an internet connection, and replaces the current licence.": "Votre fournisseur envoie un fichier .licence. Il est vérifié ici, sans connexion Internet, et remplace la licence actuelle.",
  "Your rights": "Vos droits",
  "Your role asks for a second step at each sign-in, to protect pay and personal data. Set it up now; it takes a minute.": "Votre rôle exige une deuxième étape à chaque connexion, pour protéger la paie et les données personnelles. Mettez-la en place maintenant ; cela prend une minute.",
