  "Complementary payslip of that month": "Bulletin complémentaire de ce mois",
  "A payslip with the difference, numbered and paid once Finance approves it; the month's declarations include it.": "Un bulletin portant la différence, numéroté et payé une fois approuvé par la Finance ; les déclarations du mois l'incluent.",
  "In the next payroll": "Dans la prochaine paie",
  "The difference in earnings is added to the next open payroll as back pay (or taken back), and taxed there.": "La différence de gains est ajoutée à la prochaine paie ouverte comme rappel (ou reprise), et imposée dans cette paie.",
  "Cancel the whole payslip": "Annuler tout le bulletin",
  "A complementary payslip that takes back everything, loan repayments included. What the person owes becomes an advance to recover.": "Un bulletin complémentaire qui reprend tout, remboursements de prêts compris. Ce que la personne doit devient une avance à récupérer.",
  "← Back to the payslip": "← Retour au bulletin",
  "Correct a closed payslip": "Corriger un bulletin clôturé",
  "A closed payslip is never changed. It is worked out again with today's data (salary, attendance, the month's entries and the lines you add below), and the difference is settled the way you choose.": "Un bulletin clôturé n'est jamais modifié. Il est recalculé avec les données d'aujourd'hui (salaire, présences, saisies du mois et lignes ajoutées ci-dessous), et la différence est réglée comme vous le choisissez.",
  "A complementary payslip for this payslip waits for approval: approve or discard it first.": "Un bulletin complémentaire de ce bulletin attend l'approbation : approuvez-le ou abandonnez-le d'abord.",
  "Open the corrections": "Ouvrir les corrections",
  "Lines to add for the correction": "Lignes à ajouter pour la correction",
  "Choose an element": "Choisissez un élément",
  "Add a line": "Ajouter une ligne",
  "Work it out again": "Recalculer",
  "What changes": "Ce qui change",
  "Basic salary on file for the month: {a} (paid with {b}).": "Salaire de base enregistré pour le mois : {a} (payé avec {b}).",
  "Worked out again today, this payslip does not change.": "Recalculé aujourd'hui, ce bulletin ne change pas.",
  "Now": "Maintenant",
  "Difference": "Différence",
  "Already carried into later payrolls: {a}.": "Déjà reporté sur des paies suivantes : {a}.",
  "How to settle it": "Comment la régler",
  "Reason (kept with the correction)": "Motif (conservé avec la correction)",
  "Record the correction": "Enregistrer la correction",
  "Confirm the departure of {a}?": "Confirmer le départ de {a} ?",
  "The settlement goes into the {a} payroll as pay entries, the leave paid out leaves the balance and the contract ends on {b}. Calculate that payroll again to see the last payslip.": "Le décompte entre dans la paie de {a} comme saisies de paie, les congés payés sortent du solde et le contrat prend fin le {b}. Recalculez cette paie pour voir le dernier bulletin.",
  "Confirm the departure": "Confirmer le départ",
  "Take back this departure?": "Annuler ce départ ?",
  "Take it back": "L'annuler",
  "Its pay entries are removed, the leave returns to the balance and the contract runs on.": "Ses saisies de paie sont supprimées, les congés reviennent au solde et le contrat continue.",
  "← Back to the person": "← Retour à la personne",
  "All departures": "Tous les départs",
