  "The last payslip adds the days worked in the month, the settlement and what is left of loans; CNSS and tax apply as set on each pay element. The rules are on the Rates page and must be checked with your payroll expert.": "Le dernier bulletin ajoute les jours travaillés du mois, le décompte et le reste des prêts ; la CNSS et l'impôt s'appliquent selon chaque élément de paie. Les règles sont sur la page Taux et doivent être vérifiées par votre expert paie.",
  "Save the changes": "Enregistrer les modifications",
