  "Waiting for Finance": "En attente de la Finance",
  "Carried": "Reporté",
  "Approve the complementary payslip of {a}?": "Approuver le bulletin complémentaire de {a} ?",
  "Its net is negative: what the person owes becomes a salary advance, taken from the next payrolls.": "Son net est négatif : ce que la personne doit devient une avance sur salaire, retenue sur les prochaines paies.",
  "It gets its number and can be paid with the month's payment files.": "Il reçoit son numéro et peut être payé avec les fichiers de paiement du mois.",
  "Discard this correction?": "Abandonner cette correction ?",
  "Discard": "Abandonner",
  "Pay the back pay in the next payroll?": "Payer les rappels dans la prochaine paie ?",
  "Each payslip is worked out again with the salary on file; the difference goes into the next open payroll as back pay. Calculate that payroll again afterwards.": "Chaque bulletin est recalculé avec le salaire enregistré ; la différence va dans la prochaine paie ouverte comme rappel. Recalculez ensuite cette paie.",
  "Pay the back pay": "Payer les rappels",
