  "First line holds the headers": "La première ligne contient les en-têtes",
  "Dates use dd for the day, MM for the month and yyyy for the year, for example dd/MM/yyyy or yyyyMMdd.": "Les dates utilisent dd pour le jour, MM pour le mois et yyyy pour l'année, par exemple dd/MM/yyyy ou yyyyMMdd.",
