  "Delete": "Supprimer",
  "Start from": "Partir d'un modèle",
  "Starting points only: check the order of the columns, the separator and the formats with the software that reads the file, then try one file before using it for real.": "Simples points de départ : vérifiez l'ordre des colonnes, le séparateur et les formats avec le logiciel qui lit le fichier, puis essayez un fichier avant de l'utiliser pour de vrai.",
  "Download for {a}": "Télécharger pour {a}",
  "New": "Nouveau",
  "Update": "Mise à jour",
  "What to import": "Ce qu'il faut importer",
  "1. The template": "1. Le modèle",
  "Headers in French or English are both understood. Columns marked * are required; an empty cell leaves what is already saved.": "Les en-têtes en français ou en anglais sont compris. Les colonnes marquées * sont obligatoires ; une cellule vide garde ce qui est déjà enregistré.",
  "Column": "Colonne",
  "What to write": "Quoi écrire",
  "2. Check and import": "2. Vérifier et importer",
  "Check the file": "Vérifier le fichier",
  "Importing…": "Import en cours…",
  "Imported: {a} rows saved.": "Import terminé : {a} lignes enregistrées.",
  "{a} of {b} rows need a correction. Correct them in the file and check it again; nothing was saved.": "{a} lignes sur {b} sont à corriger. Corrigez-les dans le fichier et vérifiez-le à nouveau ; rien n'a été enregistré.",
  "Every row is right ({a} rows). Import to save them.": "Toutes les lignes sont correctes ({a} lignes). Importez pour les enregistrer.",
  "Row": "Ligne",
  "Remarks": "Remarques",
  "Earlier imports": "Imports précédents",
  "Rows": "Lignes",
  "I have saved it": "Je l'ai enregistré",
  "Access key {a}": "Clé d'accès {a}",
  "Copy this key now and give it to the software that will use it. It will not be shown again.": "Copiez cette clé maintenant et donnez-la au logiciel qui l'utilisera. Elle ne sera plus affichée.",
  "Signing secret": "Secret de signature",
  "Each call carries the header X-HRPay-Signature, made with this secret. Keep it in the receiving software to check that calls come from HR Pay. It will not be shown again.": "Chaque appel porte l'en-tête X-HRPay-Signature, calculé avec ce secret. Gardez-le dans le logiciel destinataire pour vérifier que les appels viennent de HR Pay. Il ne sera plus affiché.",
  "Other software (an ERP, a time and attendance system, a bank portal) can read and send data through the HR Pay API with an access key.": "D'autres logiciels (un ERP, un système de pointage, un portail bancaire) peuvent lire et envoyer des données par l'API de HR Pay avec une clé d'accès.",
  "API description (OpenAPI)": "Description de l'API (OpenAPI)",
  "Access keys": "Clés d'accès",
  "New key": "Nouvelle clé",
  "Send the key in the header Authorization: Bearer <key>. A key can do only what it was given, and never more than the person who made it.": "Envoyez la clé dans l'en-tête Authorization: Bearer <clé>. Une clé ne peut faire que ce qui lui a été donné, et jamais plus que la personne qui l'a créée.",
  "Key": "Clé",
  "Permissions": "Permissions",
  "Expires": "Expire",
  "No key yet.": "Aucune clé pour l'instant.",
  "by {a}, {b}": "par {a}, {b}",
  "Revoked": "Révoquée",
  "Revoke the key {a}?": "Révoquer la clé {a} ?",
  "Software using this key will be refused at once.": "Les logiciels qui utilisent cette clé seront refusés immédiatement.",
  "Revoke": "Révoquer",
  "Webhooks": "Webhooks",
  "New webhook": "Nouveau webhook",
  "HR Pay calls the address (POST, JSON) when one of the chosen events happens, and tries again for a day if it does not answer.": "HR Pay appelle l'adresse (POST, JSON) quand l'un des événements choisis se produit, et réessaie pendant une journée si elle ne répond pas.",
  "Events": "Événements",
  "State": "État",
  "Last sent": "Dernier envoi",
  "No webhook yet.": "Aucun webhook pour l'instant.",
  "Paused": "En pause",
  "{a} waiting": "{a} en attente",
  "{a} failed": "{a} en échec",
  "Deliveries": "Envois",
  "Send a test": "Envoyer un test",
  "Make a new signing secret?": "Créer un nouveau secret de signature ?",
  "The old secret stops working at once: update the receiving software.": "L'ancien secret cesse de fonctionner immédiatement : mettez à jour le logiciel destinataire.",
  "New secret": "Nouveau secret",
  "It will not be shown again.": "Il ne sera plus affiché.",
  "Delete this webhook?": "Supprimer ce webhook ?",
  "How to check a call": "Comment vérifier un appel",
  "Each call carries X-HRPay-Event, X-HRPay-Delivery, X-HRPay-Timestamp and X-HRPay-Signature. The signature is sha256= followed by the HMAC-SHA256, in hexadecimal, of the timestamp, a dot and the body, with the signing secret as key. Refuse a call whose timestamp is more than five minutes old.": "Chaque appel porte X-HRPay-Event, X-HRPay-Delivery, X-HRPay-Timestamp et X-HRPay-Signature. La signature est sha256= suivi du HMAC-SHA256, en hexadécimal, de l'horodatage, d'un point et du corps, avec le secret de signature comme clé. Refusez un appel dont l'horodatage date de plus de cinq minutes.",
  "New access key": "Nouvelle clé d'accès",
  "For example: Sage accounting": "Par exemple : comptabilité Sage",
  "Expires on (optional)": "Expire le (facultatif)",
  "What the key may do": "Ce que la clé peut faire",
  "Make the key": "Créer la clé",
  "Edit the webhook": "Modifier le webhook",
  "Address (https)": "Adresse (https)",
  "Deliveries to {a}": "Envois vers {a}",
  "Event": "Événement",
  "Tries": "Essais",
  "Nothing sent yet.": "Rien envoyé pour l'instant.",
  "Sent": "Envoyé",
  "Try again": "Réessayer",
  "Recorded": "Enregistré",
  "Unknown person": "Personne inconnue",
