  "Add a clock": "Ajouter une pointeuse",
  "Serial number": "Numéro de série",
  "Site": "Site",
  "Last contact": "Dernier contact",
  "No clock yet.": "Aucune pointeuse pour l'instant.",
  "Remove the clock {a}?": "Retirer la pointeuse {a} ?",
  "Its punches are removed from this list too (check-ins already recorded stay). To keep them, turn the clock off instead.": "Ses pointages disparaissent aussi de cette liste (les présences déjà enregistrées restent). Pour les garder, désactivez plutôt la pointeuse.",
  "How to connect a clock": "Comment connecter une pointeuse",
  "Add the clock here with its serial number (Menu › System info › Device info on the clock).": "Ajoutez la pointeuse ici avec son numéro de série (Menu › Infos système › Infos appareil sur la pointeuse).",
  "On the clock, open Menu › Comm. › Cloud server setting (ADMS).": "Sur la pointeuse, ouvrez Menu › Comm. › Paramètres du serveur cloud (ADMS).",
  "Server address: {a}. Port: 443 with HTTPS on, or 80 for a clock that cannot use HTTPS.": "Adresse du serveur : {a}. Port : 443 avec HTTPS activé, ou 80 pour une pointeuse qui ne gère pas HTTPS.",
  "Turn off the proxy on the clock and restart it. Within a minute its last contact shows here.": "Désactivez le proxy sur la pointeuse et redémarrez-la. Dans la minute, son dernier contact s'affiche ici.",
  "A person is found by the number they are enrolled under on the clock: their registration number, or a clock number given in the employee import or with Link to a person below.": "Une personne est reconnue par le numéro sous lequel elle est enregistrée sur la pointeuse : son matricule, ou un numéro de pointeuse donné dans l'import des employés ou avec Associer à une personne ci-dessous.",
  "Without HTTPS, punches cross the network unencrypted: limit the clock to the addresses of your office with the allowed addresses field.": "Sans HTTPS, les pointages traversent le réseau sans chiffrement : limitez la pointeuse aux adresses de votre bureau avec le champ adresses autorisées.",
  "Punches received": "Pointages reçus",
  "Clock": "Pointeuse",
  "Every clock": "Toutes les pointeuses",
  "Outcome": "Résultat",
  "Every outcome": "Tous les résultats",
  "Time on the clock": "Heure sur la pointeuse",
  "No punch yet.": "Aucun pointage pour l'instant.",
  "Who has the number {a} on the clock?": "Qui a le numéro {a} sur la pointeuse ?",
  "The person is enrolled under this number from now on, and the punches waiting under it are recorded.": "La personne est désormais enregistrée sous ce numéro, et les pointages en attente sous ce numéro sont enregistrés.",
  "Link": "Associer",
  "Linked. No waiting punch could be recorded (see the outcome of each).": "Associé. Aucun pointage en attente n'a pu être enregistré (voir le résultat de chacun).",
