  "When nobody at the company can sign in as an administrator, reset one of them here. Only on a request you checked with the company: it is written in the company's audit log and its administrators are told.": "Quand personne dans l'entreprise ne peut se connecter comme administrateur, réinitialisez l'accès de l'un d'eux ici. Seulement sur une demande vérifiée auprès de l'entreprise : c'est inscrit dans son journal d'audit et ses administrateurs sont prévenus.",
