  "Temporary password for {a}, shown only now. Give it to them by phone, not by email; they choose their own at sign-in.": "Mot de passe provisoire de {a}, affiché seulement maintenant. Donnez-le par téléphone, pas par e-mail ; la personne choisit le sien à la connexion.",
  "The email to {a} could not be sent. Check the mail settings, or set a temporary password instead.": "L'e-mail à {a} n'a pas pu être envoyé. Vérifiez les réglages de messagerie, ou donnez plutôt un mot de passe provisoire.",
  "A link to choose a new password was sent to {a}. It works once, for 30 minutes.": "Un lien pour choisir un nouveau mot de passe a été envoyé à {a}. Il fonctionne une fois, pendant 30 minutes.",
