  "Attendance, leave and payroll for the DRC and the Republic of the Congo, in French and English. Tell us about your company; we open your trial and help you set it up.": "Pointage, congés et paie pour la RDC et la République du Congo, en français et en anglais. Parlez-nous de votre entreprise ; nous ouvrons votre essai et vous aidons à le mettre en place.",
