  "Work email": "E-mail professionnel",
  "Anything we should know (optional)": "Ce que nous devrions savoir (facultatif)",
  "For example: number of sites, the payroll software you use today": "Par exemple : nombre de sites, le logiciel de paie utilisé aujourd'hui",
  "We use these details only to answer you and open your trial.": "Nous utilisons ces informations uniquement pour vous répondre et ouvrir votre essai.",
  "Ask for a trial": "Demander un essai",
  "Terms to accept": "Conditions à accepter",
  "As an administrator of {a}, read and accept these documents to go on. They bind your company.": "En tant qu'administrateur de {a}, lisez et acceptez ces documents pour continuer. Ils engagent votre entreprise.",
  "version {a}": "version {a}",
  "I have read these documents and accept them on behalf of my company.": "J'ai lu ces documents et je les accepte au nom de mon entreprise.",
  "Accept": "Accepter",
  "Company details": "Informations de l'entreprise",
  "Legal name, address, CNSS and tax numbers, logo: they appear on payslips and declarations.": "Raison sociale, adresse, numéros CNSS et NIF, logo : ils figurent sur les bulletins et les déclarations.",
  "Workplaces": "Lieux de travail",
  "Each site with its GPS area or IP addresses, for check-in.": "Chaque site avec sa zone GPS ou ses adresses IP, pour le pointage.",
  "Structure": "Structure",
  "Directions, departments and services with their heads: approvals follow them.": "Directions, départements et services avec leurs responsables : les approbations les suivent.",
  "Working hours": "Horaires de travail",
  "Check the planned hours per day; they drive pay and lateness.": "Vérifiez les heures prévues par jour ; elles servent au calcul du salaire et des retards.",
  "Grades and salaries": "Grades et salaires",
  "Check the basic salary of each grade, from your collective agreement.": "Vérifiez le salaire de base de chaque grade, d'après votre convention collective.",
  "Have your accountant check the CNSS, IPR, INPP and ONEM rates before the first payroll.": "Faites vérifier les taux CNSS, IPR, INPP et ONEM par votre comptable avant la première paie.",
  "Check the bonuses and allowances you pay, and their rules.": "Vérifiez les primes et indemnités que vous payez, et leurs règles.",
  "The public holidays, with the date the government actually set.": "Les jours fériés, avec la date réellement fixée par le gouvernement.",
  "Import them from Excel, or add them one by one.": "Importez-les depuis Excel, ou ajoutez-les un par un.",
  "First payroll": "Première paie",
  "Calculate it, have Finance approve it, then close the month.": "Calculez-la, faites-la approuver par la Finance, puis clôturez le mois.",
  "Set up your company": "Mettre en place votre entreprise",
  "{a} of {b} steps done": "{a} étapes sur {b} terminées",
