  "Branch of activity": "Branche d'activité",
  "Telecommunications": "Télécommunications",
  "Differences report: list nets that change by more than (%)": "État des écarts : lister les nets qui varient de plus de (%)",
  "Waiting for a free worker…": "En attente d'un exécutant libre…",
  "Done.": "Terminé.",
  "You can leave this page: the bell tells you when it ends.": "Vous pouvez quitter cette page : la cloche vous prévient quand c'est terminé.",
  "My jobs": "Mes tâches",
  "Long tasks (a payroll of many people, closing a month, imports, files of every payslip) run in the background. You can leave their page: the bell tells you when one ends. Files are kept 7 days.": "Les tâches longues (la paie de nombreuses personnes, la clôture d'un mois, les imports, les fichiers de tous les bulletins) s'exécutent en arrière-plan. Vous pouvez quitter leur page : la cloche vous prévient quand l'une se termine. Les fichiers sont conservés 7 jours.",
  "No job in the last 30 days.": "Aucune tâche ces 30 derniers jours.",
  "Took": "Durée",
  "try {a}": "essai {a}",
  "Start again": "Relancer",
  "Delete old job files": "Supprimer les anciens fichiers des tâches",
  "Jobs waiting too long": "Tâches en attente trop longue",
  "Background jobs": "Tâches en arrière-plan",
  "Long tasks people start (payroll calculation, closing, imports, zips) wait in a queue in the database and run on the servers' workers. Administrators are alerted when one fails or waits more than 10 minutes.": "Les tâches longues lancées par les utilisateurs (calcul et clôture de la paie, imports, zips) attendent dans une file de la base de données et s'exécutent sur les exécutants des serveurs. Les administrateurs sont alertés quand l'une échoue ou attend plus de 10 minutes.",
  "none waiting": "aucune en attente",
  "oldest for {a} s": "la plus ancienne depuis {a} s",
  "Done in 24 h": "Terminées en 24 h",
  "{a} s on average": "{a} s en moyenne",
