  "Already calculated: calculating again replaces it.": "Déjà calculée : un nouveau calcul la remplace.",
  "Left out by HR this month": "Écartés par les RH ce mois-ci",
  "Approved annual leave waiting for its pay. Tick some, or work out all of them.": "Congés annuels approuvés en attente de leur allocation. Cochez-en, ou calculez-les tous.",
  "Base: {a}; fallback score {b}%{c}. Default pay month: {d}.": "Base : {a} ; note par défaut {b} %{c}. Mois de paiement par défaut : {d}.",
  "last basic of the year": "dernier salaire de base de l'année",
  "average basic over the year": "salaire de base moyen de l'année",
  ", prorated by months worked": ", au prorata des mois travaillés",
  "Finance approves it, then the payroll of that month puts it on each payslip, with CNSS and income tax.": "La Finance l'approuve, puis la paie de ce mois le porte sur chaque bulletin, avec la CNSS et l'IPR.",
  "Calculate the 13th month {a}": "Calculer le 13e mois {a}",
  "{n} closed payslip(s) have back pay due.": "{n} bulletin(s) clôturé(s) ont un rappel de salaire dû.",
  "The settlement goes on the last payslip, in the month of the last day.": "Le décompte va sur le dernier bulletin, du mois du dernier jour.",
  "Search an employee": "Rechercher un employé",
  "Month-end payroll": "Paie de fin de mois",
  "Quinzaine not found.": "Quinzaine introuvable.",
  "Quinzaine of {a}": "Quinzaine de {a}",
  "employees": "employés",
  "Leave pay of {a}": "Allocations de congé de {a}",
