  "Days without a check-in": "Jours sans pointage",
  "Leave waiting for a decision": "Congés en attente de décision",
  "Attendance corrections waiting": "Corrections de pointage en attente",
  "Old exchange rate": "Taux de change ancien",
  "Accept: {a}": "Accepter : {a}",
  "This accepts the {a} open line(s) of this check. The reason is kept in the audit log.": "Cela accepte les {a} ligne(s) ouvertes de ce contrôle. Le motif est conservé dans le journal d'audit.",
  "Why is it right?": "Pourquoi est-ce correct ?",
  "For example: married couple paid into one account.": "Par exemple : couple marié payé sur un seul compte.",
  "Checks before approval": "Contrôles avant approbation",
  "Thresholds": "Seuils",
  "No problem found.": "Aucun problème trouvé.",
  "{a} against the law, to fix and calculate again.": "{a} contraire(s) à la loi, à corriger puis recalculer.",
  "{a} warning(s) open, {b} accepted.": "{a} alerte(s) ouverte(s), {b} acceptée(s).",
  "The payroll can be approved.": "La paie peut être approuvée.",
  "Law": "Loi",
  "Accepted": "Acceptée",
  "Accept all": "Tout accepter",
  "The whole payroll": "Toute la paie",
  "Accepted by {a}: {b}": "Acceptée par {a} : {b}",
  "Open the file": "Ouvrir le dossier",
  "A legal problem cannot be accepted. Every other check is fixed, or accepted with a reason; calculating again starts the acceptances over.": "Un problème légal ne peut pas être accepté. Chaque autre contrôle est corrigé, ou accepté avec un motif ; un nouveau calcul remet les acceptations à zéro.",
  "Thresholds saved. They apply the next time the checks are shown.": "Seuils enregistrés. Ils s'appliquent au prochain affichage des contrôles.",
  "Payroll checks": "Contrôles de paie",
  "Flag a change in net pay above (%)": "Signaler une variation du net au-delà de (%)",
  "Flag an exchange rate older than (days)": "Signaler un taux de change de plus de (jours)",
  "Net pay is compared with the previous month, in the same currency. The overtime limit is the weekly maximum of the overtime policy.": "Le net est comparé au mois précédent, dans la même devise. La limite d'heures supplémentaires est le maximum hebdomadaire de la politique d'heures supplémentaires.",
  "Fix or accept the checks below first.": "Corrigez ou acceptez d'abord les contrôles ci-dessous.",
  "calculated": "calculée",
  "approved": "approuvée",
  "closed": "clôturée",
  "Clients": "Clients",
  "Invitations": "Invitations",
  "Invited by {a} on {b}": "Invité par {a} le {b}",
  "Rights: {a}": "Droits : {a}",
  "Decline the invitation of {a}?": "Refuser l'invitation de {a} ?",
  "Your clients": "Vos clients",
  "No client yet. A company invites your firm from its own HR Pay, with your administrator's email address.": "Aucun client pour l'instant. Une entreprise invite votre cabinet depuis son propre HR Pay, avec l'adresse email de votre administrateur.",
  "Your firm's administrator has not given you a client yet.": "L'administrateur de votre cabinet ne vous a pas encore confié de client.",
  "Client": "Client",
  "Checks": "Contrôles",
  "{a} open": "{a} ouvert(s)",
  "{a} to pay": "{a} à payer",
  "Your firm": "Votre cabinet",
  "The client": "Le client",
  "Staff ({a})": "Équipe ({a})",
  "Stop working for {a}?": "Arrêter de travailler pour {a} ?",
  "Stop": "Arrêter",
  "Your firm loses its access to this client at once. The client can invite you again.": "Votre cabinet perd aussitôt l'accès à ce client. Le client peut vous inviter de nouveau.",
  "Each client chose what your firm may do in its company. Everything you change there is in its audit log under your name and your firm's.": "Chaque client a choisi ce que votre cabinet peut faire dans son entreprise. Tout ce que vous y modifiez figure dans son journal d'audit, à votre nom et à celui du cabinet.",
  "Invoices your firm pays": "Factures payées par votre cabinet",
  "Pay them like any HR Pay invoice, with the invoice number as the reference. An unpaid invoice makes that client read-only after the grace days.": "Payez-les comme toute facture HR Pay, avec le numéro de facture comme référence. Une facture impayée met ce client en lecture seule après le délai de grâce.",
  "Commissions": "Commissions",
  "For clients that pay HR Pay themselves, your firm earns {a} % of each paid invoice before tax. For clients your firm pays for, the price is {b} % lower.": "Pour les clients qui paient eux-mêmes HR Pay, votre cabinet touche {a} % de chaque facture payée, hors taxes. Pour les clients que votre cabinet paie, le prix est réduit de {b} %.",
  "No commission yet.": "Aucune commission pour l'instant.",
  "Paid out": "Versée",
  "Work for {a}": "Travailler pour {a}",
  "Who pays HR Pay for this client?": "Qui paie HR Pay pour ce client ?",
  "The client pays its subscription; your firm earns {a} % of each paid invoice.": "Le client paie son abonnement ; votre cabinet touche {a} % de chaque facture payée.",
  "Your firm pays, {a} % below the price, and bills the client itself.": "Votre cabinet paie, {a} % sous le prix, et facture lui-même le client.",
  "Who works for {a}?": "Qui travaille pour {a} ?",
  "administrator: all clients": "administrateur : tous les clients",
  "Invited, waiting for the firm": "Invité, en attente du cabinet",
  "Working for you": "Travaille pour vous",
  "Accounting firm": "Cabinet comptable",
  "Invite a firm": "Inviter un cabinet",
  "Your accounting firm then works in your HR Pay with the rights you choose, without you sharing a password. You can change them or end the access at any time.": "Votre cabinet comptable travaille alors dans votre HR Pay avec les droits que vous choisissez, sans partager de mot de passe. Vous pouvez les modifier ou mettre fin à l'accès à tout moment.",
  "Invitation sent. The firm accepts it from its own HR Pay.": "Invitation envoyée. Le cabinet l'accepte depuis son propre HR Pay.",
  "Email address of the firm's administrator": "Adresse email de l'administrateur du cabinet",
  "What the firm may do: the rights of these roles": "Ce que le cabinet peut faire : les droits de ces rôles",
  "The firm never gets your subscription, nor the right to invite other firms.": "Le cabinet n'a jamais accès à votre abonnement, ni le droit d'inviter d'autres cabinets.",
  "Data processing clause ({a})": "Clause de traitement des données ({a})",
  "Your company remains responsible for its employees' personal data. The firm processes them only on your behalf, for the work you give it, and keeps them confidential. It lets its staff see only what that work needs, keeps nothing once the access ends, and tells you without delay of any breach. Every page its staff open and every change they make is kept and shown to you. DRC: Code du numérique (loi 23/010); Republic of the Congo: loi 29-2019.": "Votre entreprise reste responsable des données personnelles de ses employés. Le cabinet les traite uniquement pour votre compte, pour le travail que vous lui confiez, et en garantit la confidentialité. Il ne laisse son personnel voir que ce que ce travail exige, ne conserve rien une fois l'accès terminé et vous informe sans délai de toute violation. Chaque page ouverte et chaque modification par son personnel est conservée et vous est montrée. RDC : Code du numérique (loi 23/010) ; République du Congo : loi 29-2019.",
  "I accept this clause on behalf of the company": "J'accepte cette clause au nom de l'entreprise",
  "Invite": "Inviter",
  "Firms": "Cabinets",
  "Firm": "Cabinet",
  "Rights": "Droits",
  "Pages opened": "Pages ouvertes",
  "{a}, {b}": "{a}, {b}",
  "The firm": "Le cabinet",
  "Your company": "Votre entreprise",
  "End the access of {a}?": "Mettre fin à l'accès de {a} ?",
  "End the access": "Mettre fin à l'accès",
