  'No contract': 'Sans contrat',
  'No contract today. The first salary is set with the contract; raises and promotions come after.': 'Pas de contrat aujourd\'hui. Le premier salaire se fixe avec le contrat ; les augmentations et promotions viennent ensuite.',
  'No contract: no hire date.': 'Pas de contrat : pas de date d\'embauche.',
  'Not an employee': 'Non-employé',
  'Not an employee (no contract)': 'Non-employé (pas de contrat)',
  'Only employees with no contract today': 'Seulement les employés sans contrat aujourd\'hui',
  'Only for accounts that are not staff: the provider\'s administrator, an outside accounting firm, a consultant. They never check in, take leave or get paid. Everyone else needs a contract.': 'Seulement pour les comptes qui ne font pas partie du personnel : l\'administrateur du fournisseur, un cabinet comptable externe, un consultant. Ils ne pointent pas, ne prennent pas de congé et ne sont pas payés. Tous les autres ont besoin d\'un contrat.',
  'Saved. New employees get the next number from now on.': 'Enregistré. Les nouveaux employés reçoivent désormais le numéro suivant.',
  'Set by the first contract.': 'Fixée par le premier contrat.',
  'Set it above your existing numbers. Numbers already used are skipped.': 'Mettez-le au-dessus de vos numéros existants. Les numéros déjà utilisés sont sautés.',
  'Starts again at 1 each year': 'Recommence à 1 chaque année',
  'The company numbers new employees automatically.': 'L\'entreprise numérote automatiquement les nouveaux employés.',
  'The first salary is set here: the agreed net, or the grade\'s basic. Raises and promotions come later.': 'Le premier salaire se fixe ici : le net convenu, ou le salaire de base du grade. Les augmentations et promotions viennent ensuite.',
  'The hire date. Empty: the contract start. Give an earlier date only for someone hired before this contract (seniority).': 'La date d\'embauche. Vide : le début du contrat. Donnez une date antérieure seulement pour une personne embauchée avant ce contrat (ancienneté).',
  'This account is not an employee: no contract and no salary.': 'Ce compte n\'est pas un employé : pas de contrat ni de salaire.',
  'When on, the employee ID is not typed when a person is created; an import row with no employee ID gets one too. Existing employee IDs never change.': 'Activé, le matricule n\'est pas saisi à la création d\'une personne ; une ligne d\'import sans matricule en reçoit un aussi. Les matricules existants ne changent jamais.',
  '{YYYY} or {YY}: the year · {SITE}: the site code · {SEQ:5}: the counter on 5 digits (required)': '{YYYY} ou {YY} : l\'année · {SITE} : le code du site · {SEQ:5} : le compteur sur 5 chiffres (obligatoire)',
