  'Document owner': 'Propriétaire du document',
  'Empty fields take the value shown in grey. The draft is given to the employee at least two working days before signing (Labour Code art. 46); the signed contract goes to the ONEM visa within 15 days (art. 47).': 'Un champ vide prend la valeur affichée en gris. Le projet est remis au travailleur au moins deux jours ouvrables avant la signature (Code du travail art. 46) ; le contrat signé est soumis au visa de l\'ONEM dans les 15 jours (art. 47).',
  'Humanitarian activities (arrêté 063/2011)': 'Activités humanitaires (arrêté 063/2011)',
  'In a contract, the text after a line with only --- is printed in small print after the signatures. The parties\' full identity and family are added in an annex.': 'Dans un contrat, le texte après une ligne ne contenant que --- est imprimé en petits caractères après les signatures. L\'identité complète des parties et la situation familiale sont ajoutées en annexe.',
