  "Closed months as paid; the others projected with what is known today: salary changes already recorded, anniversary raises, annual leave and its allocation, the 13th month, loans, the end of a fixed-term contract, children reaching the age limit and rates entered for later dates.": "Les mois clôturés tels que payés ; les autres projetés avec ce qui est connu aujourd'hui : changements de salaire déjà enregistrés, augmentations d'ancienneté, congé annuel et son allocation, 13e mois, prêts, fin d'un CDD, enfants qui atteignent la limite d'âge et taux saisis pour des dates futures.",
