  "Annual leave: {a} days now, {b} still to earn this year, {c} asked for and not approved yet: about {d} days left on 31 December.": "Congé annuel : {a} jours aujourd'hui, {b} encore à acquérir cette année, {c} demandés et pas encore approuvés : environ {d} jours restants au 31 décembre.",
  "Worth {a} at {b} a day, paid only when the contract ends.": "Valeur {a} à {b} par jour, payée seulement à la fin du contrat.",
  "Everyone under contract in the year, projected one by one like the year projection, then added up. A large company takes a few minutes: it runs in the background (My jobs).": "Toutes les personnes sous contrat dans l'année, projetées une à une comme la projection annuelle, puis additionnées. Une grande entreprise prend quelques minutes : le calcul tourne en arrière-plan (Mes tâches).",
