  "Increase: {a}": "Augmentation : {a}",
  "General salary increase": "Augmentation générale des salaires",
  "The grade bases go up by the percentage from the month chosen, and everyone on those grades gets the same amount on their basic salary (Code du travail art. 86). Their salary complement does not change. Nothing changes until another person approves it.": "Les bases des grades augmentent du pourcentage à partir du mois choisi, et chaque personne de ces grades reçoit le même montant sur son salaire de base (Code du travail art. 86). Son complément de salaire ne change pas. Rien ne change tant qu'une autre personne ne l'a pas approuvée.",
  "e.g. 5% from January": "ex. 5 % dès janvier",
