  "Approve \"{a}\"?": "Approuver « {a} » ?",
  "The grade bases and the basic salaries change from {a}; months already approved get back pay on the next payroll. It can be undone until a later payroll is approved.": "Les bases des grades et les salaires de base changent à partir de {a} ; les mois déjà approuvés reçoivent un rappel de salaire sur la prochaine paie. Elle peut être annulée tant qu'une paie suivante n'est pas approuvée.",
