  "Per diem scale": "Barème des per diem",
  "A daily amount for meals and small costs, by grade category and zone, and a nightly amount used only when the company does not book the hotel. Within the scale, the per diem is a cost of the mission, not pay. A higher rate on a mission puts the difference on the payslip, with CNSS and income tax. Amounts are to be confirmed by your payroll adviser.": "Un montant journalier pour les repas et petits frais, par catégorie de grade et zone, et un montant par nuit utilisé seulement quand la société ne réserve pas l'hôtel. Dans la limite du barème, le per diem est un frais de mission, pas une rémunération. Un taux plus élevé sur une mission met la différence sur le bulletin, avec CNSS et impôt. Montants à confirmer par votre conseiller paie.",
