  'Discipline register': 'Registre disciplinaire',
  'Propose a case': 'Proposer un dossier',
  'Before any sanction the employee is invited to a hearing to explain themself (Labour Code art. 62). A sanction never takes money from pay: fines are forbidden (art. 111). Only a mise à pied makes its days unpaid.': 'Avant toute sanction, l\'employé est convoqué à un entretien pour s\'expliquer (Code du travail, art. 62). Une sanction ne retire jamais d\'argent du salaire : les amendes sont interdites (art. 111). Seule une mise à pied rend ses jours non payés.',
  'Propose a case for someone of your team: HR reviews it, hears the employee and decides.': 'Proposez un dossier pour une personne de votre équipe : les RH l\'examinent, entendent l\'employé et décident.',
  'Every case': 'Tous les dossiers',
