  'Send the letter': 'Envoyer la lettre',
  'Record the departure with the reason "serious misconduct" on the Departures page: it ends the contract and works out the final pay.': 'Enregistrez le départ avec le motif « faute lourde » sur la page Départs : il met fin au contrat et calcule le décompte final.',
  'Contested by the employee': 'Contestée par l\'employé',
  'Cancelled on {a}: {b}': 'Annulé le {a} : {b}',
  'Note to the head (required to reject)': 'Note au chef (obligatoire pour rejeter)',
