  'Reject the case': 'Rejeter le dossier',
  'Day and time': 'Jour et heure',
  'For example: the HR office': 'Par exemple : le bureau des RH',
  'A letter inviting the employee is drafted from the template "Invitation to a disciplinary hearing". Read it, then send it: the employee signs it for receipt in HR Pay.': 'Une lettre de convocation est préparée à partir du modèle « Convocation à un entretien disciplinaire ». Relisez-la, puis envoyez-la : l\'employé la signe pour réception dans HR Pay.',
  'Move the hearing': 'Déplacer l\'entretien',
  'Set the hearing': 'Fixer l\'entretien',
  'Held on': 'Tenu le',
  'The employee did not come': 'L\'employé n\'est pas venu',
  'What the employee said in their defence': 'Ce que l\'employé a dit pour sa défense',
  'Notes (not shown to the employee)': 'Notes (non montrées à l\'employé)',
  'Record the hearing': 'Enregistrer l\'entretien',
  'No sanction: close the case': 'Aucune sanction : clore le dossier',
  'The days are recorded as unpaid leave: the employee does not work and is not paid for them. At most 15 days at a time and 30 days a year (art. 57), and only when your company rules provide it.': 'Les jours sont enregistrés comme congé non payé : l\'employé ne travaille pas et n\'est pas payé. Au plus 15 jours à la fois et 30 jours par an (art. 57), et seulement si votre règlement d\'entreprise le prévoit.',
  'After the letter, record the departure on the Departures page.': 'Après la lettre, enregistrez le départ sur la page Départs.',
  'Reasons for the decision': 'Motifs de la décision',
  'Decide the sanction': 'Décider la sanction',
  'Close without sanction': 'Clore sans sanction',
  'Cancel this case…': 'Annuler ce dossier…',
  'Why is it cancelled?': 'Pourquoi est-il annulé ?',
  'The case stays in the history but no longer counts. The days of a mise à pied are given back.': 'Le dossier reste dans l\'historique mais ne compte plus. Les jours de mise à pied sont rendus.',
  'Cancel the case': 'Annuler le dossier',
  'Keep it': 'Le garder',
  'Edit the letter': 'Modifier la lettre',
  'Discipline': 'Discipline',
  'The letters themselves are in your documents above. You may contest a sanction in writing once; HR reads it and may withdraw the sanction.': 'Les lettres elles-mêmes sont dans vos documents ci-dessus. Vous pouvez contester une sanction par écrit, une fois ; les RH la lisent et peuvent retirer la sanction.',
  'Cancelled: it no longer counts.': 'Annulée : elle ne compte plus.',
  'Not decided yet': 'Pas encore décidé',
