  'Why do you contest it?': 'Pourquoi la contestez-vous ?',
  '← Discipline register': '← Registre disciplinaire',
  'Discipline settings': 'Paramètres de discipline',
  'Our company rules (or the collective agreement) provide the mise à pied': 'Notre règlement d\'entreprise (ou la convention collective) prévoit la mise à pied',
  'Labour Code art. 57: a mise à pied is possible only when the contract, the collective agreement or the company rules provide it. Company rules are compulsory from 20 workers and are filed with the labour court (Arrêté 70/0016).': 'Code du travail, art. 57 : une mise à pied n\'est possible que si le contrat, la convention collective ou le règlement d\'entreprise la prévoit. Le règlement d\'entreprise est obligatoire à partir de 20 travailleurs et déposé au tribunal du travail (Arrêté 70/0016).',
  'Days of one mise à pied, at most': 'Jours d\'une mise à pied, au plus',
  'Days of mise à pied in a year, at most': 'Jours de mise à pied par an, au plus',
  'Sanctions count in the rankings for (months)': 'Les sanctions comptent dans les classements pendant (mois)',
  'Lateness follow-up from (late days in a month)': 'Suivi des retards à partir de (jours de retard dans un mois)',
  'The labour code sets no time after which a sanction is erased; 24 months is our proposal, to confirm with your labour law adviser.': 'Le Code du travail ne fixe pas de délai d\'effacement des sanctions ; 24 mois est notre proposition, à confirmer avec votre conseiller en droit du travail.',
  'Discipline settings saved.': 'Paramètres de discipline enregistrés.',
  'The sanctions of the Labour Code (art. 54), lightest first. The weight orders the sanction ranking. Fines are not a sanction: the code forbids them (art. 111). Each sanction has its letter template, which you can change under Hiring and departure settings.': 'Les sanctions du Code du travail (art. 54), de la plus légère à la plus lourde. Le poids ordonne le classement des sanctions. Les amendes ne sont pas une sanction : le code les interdit (art. 111). Chaque sanction a son modèle de lettre, modifiable dans les paramètres d\'embauche et de départ.',
  'Effect': 'Effet',
