  'Sanction saved.': 'Sanction enregistrée.',
  'A transfer or a promotion goes through Promote or transfer, which writes the note de mutation or the avenant to sign.': 'Une mutation ou une promotion passe par Promouvoir ou muter, qui rédige la note de mutation ou l\'avenant à signer.',
