  'The file comes filled with what HR Pay holds today: change what you need, then import it back. Rows left as they are change nothing.': 'Le fichier est rempli avec ce que HR Pay contient aujourd\'hui : modifiez ce qu\'il faut, puis importez-le. Les lignes laissées telles quelles ne changent rien.',
