  'Written in the avenant, 6 months at most (Labour Code art. 43). If it is not conclusive, the employee returns to the previous post.': 'Écrite dans l\'avenant, 6 mois au plus (Code du travail, art. 43). Si l\'essai n\'est pas concluant, le travailleur retrouve son poste précédent.',
  'Unit and place of work': 'Unité et lieu de travail',
  'A transfer outside the place of employment: the company owes decent housing for the worker and the family, or an allowance (Labour Code art. 138).': 'Une mutation hors du lieu d\'emploi : l\'entreprise doit un logement décent au travailleur et à sa famille, ou une indemnité (Code du travail, art. 138).',
