  'A reclassification corrects the job without a document to sign.': 'Un reclassement corrige le poste sans document à signer.',
  'HR Pay writes the {a} for the employee to sign; it stays a draft until you send it. Seniority does not change.': 'HR Pay rédige {a} à faire signer à l\'employé ; il reste en brouillon jusqu\'à son envoi. L\'ancienneté ne change pas.',
