  'fixed-term contract ending on {a}': 'CDD se terminant le {a}',
  'The contract goes on. The confirmation letter is prepared as a draft for you to read and send.': 'Le contrat continue. La lettre de confirmation est préparée en brouillon pour que vous la relisiez et l\'envoyiez.',
  'Who ends it': 'Qui y met fin',
  'In DR Congo either party gives 3 working days\' notice, none in the first 3 days of the trial (art. 71). A departure is saved as a draft for you to check and confirm.': 'En RDC, chaque partie donne un préavis de 3 jours ouvrables, aucun pendant les 3 premiers jours de l\'essai (art. 71). Un départ est enregistré en brouillon pour que vous le vérifiiez et le confirmiez.',
  'New end date': 'Nouvelle date de fin',
  'A fixed-term contract lasts two years at most and is renewed once (art. 41). The new contract starts on {a} with the same grade and basic salary.': 'Un CDD dure deux ans au plus et n\'est renouvelé qu\'une fois (art. 41). Le nouveau contrat commence le {a} avec le même grade et le même salaire de base.',
  'Permanent from': 'CDI à partir du',
  'Same grade and basic salary; seniority runs from the first contract.': 'Même grade et même salaire de base ; l\'ancienneté court depuis le premier contrat.',
  'A departure "end of contract" on {a} is saved as a draft for you to check and confirm.': 'Un départ « fin de contrat » au {a} est enregistré en brouillon pour que vous le vérifiiez et le confirmiez.',
  'Delegate': 'Délégué',
  'Alternate': 'Suppléant',
  'Election': 'Élection',
  'Meeting with the delegates': 'Réunion avec la délégation',
  'Company rules sent': 'Règlement d\'entreprise transmis',
  'Staff representation': 'Représentation du personnel',
  'Add a delegate': 'Ajouter un délégué',
  'The délégation syndicale is elected in every establishment of at least {a} workers, for three years (arrêté 048/2015). Dismissing or transferring a delegate or an alternate needs the labour inspector\'s authorisation first (arrêté 036/95): HR Pay stops the dismissal, the departure and the transfer until it is recorded here.': 'La délégation syndicale est élue dans tout établissement d\'au moins {a} travailleurs, pour trois ans (arrêté 048/2015). Licencier ou muter un délégué ou un suppléant exige d\'abord l\'autorisation de l\'inspecteur du travail (arrêté 036/95) : HR Pay bloque le licenciement, le départ et la mutation tant qu\'elle n\'est pas enregistrée ici.',
  'Workers under contract': 'Travailleurs sous contrat',
