  'Add a record': 'Ajouter un enregistrement',
  'The employer meets the délégation every three months; the minutes, signed by all, go to the labour inspector within eight days (art. 37). The company rules go to the delegates and the inspector (Labour Code art. 157).': 'L\'employeur réunit la délégation tous les trois mois ; le procès-verbal, signé par tous, va à l\'inspecteur du travail dans la huitaine (art. 37). Le règlement d\'entreprise est transmis à la délégation et à l\'inspecteur (Code du travail art. 157).',
