  'Every accident at work, on the way to or from work, and every occupational disease. Declare it to the CNSS with a copy to the labour inspection and the victim (DRC: 60 days for an accident, 120 for a disease). Days off are paid at two thirds for six months (art. 106); the accident day is paid in full.': 'Tout accident survenu au travail, sur le trajet du travail, et toute maladie professionnelle. Déclarez-le à la CNSS avec copie à l\'inspection du travail et à la victime (RDC : 60 jours pour un accident, 120 pour une maladie). Les jours d\'arrêt sont payés aux deux tiers pendant six mois (art. 106) ; le jour de l\'accident est payé en entier.',
