  'The accident leave it recorded is cancelled.': 'Le congé d\'accident enregistré est annulé.',
  'Drafted letters are on the person\'s page, under Documents and letters, to read and send.': 'Les lettres préparées sont sur la page de la personne, dans Documents et lettres, à relire et envoyer.',
