  'Last day off': 'Dernier jour d\'arrêt',
  'The days off are recorded as work accident leave, paid at its share for six months at most. From 30 days off, a return-to-work visit is planned.': 'Les jours d\'arrêt sont enregistrés en congé d\'accident du travail, payé à son taux pendant six mois au plus. À partir de 30 jours d\'arrêt, une visite de reprise est planifiée.',
  'Declaration of the accident': 'Déclaration de l\'accident',
