  'Copy to the labour inspection on': 'Copie à l\'inspection du travail le',
  'Copy to the victim on': 'Copie à la victime le',
  'From {a} workers, a health and safety committee (CSHE): the employer presides, with the safety head, the doctor, the training head and worker members named by the delegates, for two years. It meets at least every two months, inspects the workplace every month, and sends a yearly report by 31 March (arrêté 043/2008).': 'À partir de {a} travailleurs, un comité de sécurité, d\'hygiène et d\'embellissement des lieux de travail (CSHE) : l\'employeur le préside, avec le chef de la sécurité, le médecin, le responsable de la formation et des membres travailleurs désignés par la délégation syndicale, pour deux ans. Il se réunit au moins tous les deux mois, inspecte les lieux chaque mois et envoie un rapport annuel avant le 31 mars (arrêté 043/2008).',
  'No rule on a health and safety committee is known for this country yet: the committee can still be kept here.': 'Aucune règle sur le comité de sécurité n\'est encore connue pour ce pays : le comité peut tout de même être suivi ici.',
