  "Delete this job family?": "Supprimer cette famille d'emplois ?",
  "Its jobs stay, with no family.": "Ses emplois restent, sans famille.",
  "Each job has its description (fiche de poste), the grades it is paid in and so its legal category, and whether it is unskilled (a trial of one month at most). Each save keeps a version: a contract keeps the text it was signed with.": "Chaque emploi a sa fiche de poste, les grades dans lesquels il est payé et donc sa catégorie légale, et s'il s'agit d'un emploi de manœuvre (essai d'un mois au plus). Chaque enregistrement garde une version : un contrat garde le texte avec lequel il a été signé.",
