  "Delete this step?": "Supprimer cette étape ?",
  "For each job, the jobs a person can move up to and what it takes: years in the job and the average of the approved evaluations of the last two years. A training or diploma is checked by hand. The person's page shows the next steps; the promotion itself goes through Career moves, with its letter.": "Pour chaque emploi, les emplois vers lesquels une personne peut évoluer et les conditions : années dans l'emploi et moyenne des évaluations approuvées des deux dernières années. Une formation ou un diplôme se vérifie à la main. La fiche de la personne montre les étapes suivantes ; la promotion elle-même passe par Carrière, avec sa lettre.",
