  "The people who meet every condition of a next job on the ladder: years in the job and evaluation average. Check what is also needed, then promote from the person's page (Career moves).": "Les personnes qui remplissent toutes les conditions d'un emploi suivant sur l'échelle : années dans l'emploi et moyenne des évaluations. Vérifiez ce qui est requis aussi, puis promouvez depuis la fiche de la personne (Carrière).",
