  "Last score: {a} %": "Dernière note : {a} %",
  "Write each person's objectives for the year, with weights that add up to 100 %, then share them. Around mid-year, record a check-in for each objective. The evaluation scores them when its template has the Individual objectives criterion.": "Rédigez les objectifs de l'année de chaque personne, avec des poids qui totalisent 100 %, puis partagez-les. Vers la mi-année, faites un point d'étape pour chaque objectif. L'évaluation les note quand son modèle comprend le critère Objectifs individuels.",
