  "In the DRC, the share of foreign staff is capped by sector and grade (AM 70/0010). A foreign worker needs a work card, and the post must stay unfilled 30 days after it is declared (AD 87/005).": "En RDC, la part du personnel étranger est plafonnée par secteur et par catégorie (AM 70/0010). Un travailleur étranger a besoin d'une carte de travail, et le poste doit rester vacant 30 jours après sa déclaration (AD 87/005).",
