  "A unit head asks to hire for their unit; HR approves, and the approved request becomes a vacancy with its ad written from the job description.": "Le chef d'une unité demande à recruter pour son unité ; les RH approuvent, et la demande approuvée devient un poste à pourvoir dont l'annonce reprend la fiche de poste.",
