  "Days for staff only": "Jours réservés au personnel",
  "Ad": "Annonce",
  "A line starting with \"## \" is a heading. The text from the job description is a starting point: keep it short and concrete.": "Une ligne qui commence par « ## » est un titre. Le texte de la fiche de poste est un point de départ : restez bref et concret.",
  "Words to check in the ad": "Mots à vérifier dans l'annonce",
  "An ad must not exclude people for their sex, age, marital status, religion, origin, nationality, pregnancy or disability, unless the law requires it for this job (AM 012/2008 art. 15; Labour Code art. 1, 128).": "Une annonce ne doit exclure personne en raison du sexe, de l'âge, de l'état civil, de la religion, de l'origine, de la nationalité, de la grossesse ou du handicap, sauf si la loi l'exige pour cet emploi (AM 012/2008 art. 15 ; Code du travail art. 1 et 128).",
  "Declared to ONEM": "Déclaré à l'ONEM",
