  "Give every score, from 1 to 5.": "Donnez chaque note, de 1 à 5.",
  "My scorecard": "Ma grille d'évaluation",
  "1 = far below what the job needs, 3 = what the job needs, 5 = well above. Score only what the job description asks, never sex, age, family, religion or origin.": "1 = bien en dessous de ce que demande le poste, 3 = ce que demande le poste, 5 = bien au-dessus. Notez seulement ce que demande la fiche de poste, jamais le sexe, l'âge, la famille, la religion ou l'origine.",
  "Do you recommend this person?": "Recommandez-vous cette personne ?",
  "Save the offer": "Enregistrer l'offre",
  "Net per month (optional)": "Net mensuel (facultatif)",
  "Start date": "Date d'entrée",
  "End date (fixed term)": "Date de fin (CDD)",
  "Letter text (optional: left empty, it is written from the terms above)": "Texte de la lettre (facultatif : laissé vide, il est rédigé à partir des conditions ci-dessus)",
  "Without a net, the basic of the grade applies. The net becomes the agreed net of the first contract, solved as grade basic plus complement.": "Sans net, le salaire de base du grade s'applique. Le net devient le net convenu du premier contrat, réparti entre la base du grade et le complément.",
  "Hire {a}": "Engager {a}",
  "This creates the employee in the vacancy's unit with the first contract from the offer, opens the hiring checklist, and starts the hire declaration to ONEM.": "Cela crée l'employé dans l'unité du poste avec le premier contrat issu de l'offre, ouvre la liste d'embauche et lance la déclaration d'embauche à l'ONEM.",
  "Registration number (optional)": "Matricule (facultatif)",
  "Empty: numbered by HR Pay when the company has a format": "Vide : numéroté par HR Pay si l'entreprise a un format",
  "Date of the waiver of the Président du Tribunal de paix": "Date de la dérogation du Président du Tribunal de paix",
  "The contract can be signed from {a}, two working days after the draft reached the person (art. 46).": "Le contrat peut être signé à partir du {a}, deux jours ouvrables après la remise du projet (art. 46).",
  "Interviews I sit on": "Entretiens où je siège",
  "No interview.": "Aucun entretien.",
  "To fill": "À remplir",
