  "Date sent": "Date d'envoi",
  "Careers page by HR Pay": "Page carrières par HR Pay",
  "Apply by {d}": "Postuler avant le {d}",
  "Work with us": "Travaillez avec nous",
  "No offer is open right now. Come back soon.": "Aucune offre n'est ouverte pour le moment. Revenez bientôt.",
  "Attach your CV.": "Joignez votre CV.",
  "The CV is larger than 5 MB.": "Le CV dépasse 5 Mo.",
  "All our offers": "Toutes nos offres",
  "Thank you. Your application has been received; you will get an email to confirm it.": "Merci. Votre candidature est bien reçue ; un e-mail de confirmation vous est envoyé.",
  "Cover letter (optional)": "Lettre de motivation (facultatif)",
  "I agree that {company} keeps my application and CV to assess it, until 12 months after the offer closes. I can withdraw at any time with the link in the confirmation email.": "J'accepte que {company} conserve ma candidature et mon CV pour l'évaluer, jusqu'à 12 mois après la clôture de l'offre. Je peux la retirer à tout moment avec le lien de l'e-mail de confirmation.",
  "Keep my application longer, for future offers.": "Conserver ma candidature plus longtemps, pour de futures offres.",
  "Applying is free. The company never asks candidates for money.": "Postuler est gratuit. L'entreprise ne demande jamais d'argent aux candidats.",
  "Send my application": "Envoyer ma candidature",
  "Withdraw my application": "Retirer ma candidature",
  "Your application is withdrawn and your data is deleted.": "Votre candidature est retirée et vos données sont effacées.",
  "Your application for {title} at {company} will be withdrawn, and your data deleted. This cannot be undone.": "Votre candidature au poste de {title} chez {company} sera retirée et vos données effacées. C'est définitif.",
  "Withdraw and delete my data": "Retirer et effacer mes données",
  "Selected": "Retenu(e)",
  "Under review": "En cours d'examen",
  "Job offers": "Offres d'emploi",
  "Open posts in the company. Apply in one click: HR sees your file, and your manager hears of it only if you are shortlisted.": "Postes ouverts dans l'entreprise. Postulez en un clic : les RH voient votre dossier, et votre responsable n'est informé que si vous êtes présélectionné(e).",
  "No offer is open right now.": "Aucune offre n'est ouverte pour le moment.",
  "HR is told that you no longer apply. You can apply again while the offer is open.": "Les RH sont informés que vous ne postulez plus. Vous pouvez postuler à nouveau tant que l'offre est ouverte.",
  "Job offer": "Offre d'emploi",
  "A word for HR (optional)": "Un mot pour les RH (facultatif)",
  "Why this post interests you, what you would bring": "Pourquoi ce poste vous intéresse, ce que vous apporteriez",
  "A public page lists the vacancies marked public, and those for staff first once their days have passed. Candidates apply there without an account; staff see every open vacancy on Job offers.": "Une page publique présente les postes marqués publics, et ceux réservés d'abord au personnel une fois leurs jours écoulés. Les candidats y postulent sans compte ; le personnel voit tous les postes ouverts dans Offres d'emploi.",
  "Short name in the link": "Nom court dans le lien",
  "3 to 40 lowercase letters, digits or dashes.": "3 à 40 lettres minuscules, chiffres ou tirets.",
  "The careers page is on": "La page carrières est active",
  "Page link": "Lien de la page",
  "Staff see this offer on Job offers. It is not on the careers page.": "Le personnel voit cette offre dans Offres d'emploi. Elle n'est pas sur la page carrières.",
  "Turn the careers page on to share this offer outside the company.": "Activez la page carrières pour diffuser cette offre hors de l'entreprise.",
  "Copy the link": "Copier le lien",
  "Share the offer": "Diffuser l'offre",
