  "told on {a}": "informé le {a}",
  "told at the shortlist": "informé à la présélection",
  "The ladder leads here and its conditions are met.": "Le parcours de carrière mène à ce poste et ses conditions sont remplies.",
  "The ladder leads here, but not all conditions are met.": "Le parcours de carrière mène à ce poste, mais toutes ses conditions ne sont pas remplies.",
  "Asks {y} years in the job": "Demande {y} ans dans l'emploi",
  "an average of {s} %": "une moyenne de {s} %",
  "No ladder leads from their job to this one.": "Aucun parcours de carrière ne mène de son emploi à celui-ci.",
  "Move {a} to this post": "Affecter {a} à ce poste",
  "From the offer's start date, the employee moves to the vacancy's unit, job and grade: a promotion, a transfer or both. The avenant is drafted in Documents and letters, and the pay follows the new grade.": "À la date d'entrée de l'offre, l'employé passe à l'unité, à l'emploi et au grade du poste : promotion, mutation ou les deux. L'avenant est préparé dans Documents et lettres, et la paie suit le nouveau grade.",
  "Apply for this post": "Postuler",
  "Show closed onboardings": "Afficher les accueils clôturés",
  "No buddy yet": "Aucun parrain pour l'instant",
  "One-month review": "Point à un mois",
  "End-of-trial review": "Bilan de fin d'essai",
  "Sent. HR checks your details and papers and comes back to you if something is missing.": "Envoyé. Les RH vérifient vos informations et vos pièces et reviennent vers vous s'il manque quelque chose.",
  "Saved. You can come back to this page until your first day.": "Enregistré. Vous pouvez revenir sur cette page jusqu'à votre premier jour.",
  "The file is larger than 5 MB.": "Le fichier dépasse 5 Mo.",
  "Welcome, {name}": "Bienvenue, {name}",
  "You start at {company} on {d}. Fill in what you can before then: HR prepares your file, your pay and your first day with it. Nothing here is shared outside HR.": "Vous commencez chez {company} le {d}. Remplissez ce que vous pouvez d'ici là : les RH préparent ainsi votre dossier, votre paie et votre premier jour. Rien ici n'est partagé en dehors des RH.",
  "Sent to HR on {d}. You can still correct it until your first day.": "Envoyé aux RH le {d}. Vous pouvez encore corriger jusqu'à votre premier jour.",
  "About you": "Vous",
  "Street and number": "Avenue et numéro",
  "CNSS number (if you already have one)": "Numéro CNSS (si vous en avez déjà un)",
  "How you want to be paid": "Comment vous souhaitez être payé(e)",
  "Your family": "Votre famille",
  "Your spouse and children give the family allowances and the tax reduction. HR asks for the certificates.": "Votre conjoint et vos enfants donnent droit aux allocations familiales et à la réduction d'impôt. Les RH vous demanderont les attestations.",
  "Add a family member": "Ajouter un membre de la famille",
  "Your papers": "Vos pièces",
  "A photo or a scan: PDF, JPEG or PNG, 5 MB at most. HR checks each one.": "Une photo ou un scan : PDF, JPEG ou PNG, 5 Mo au plus. Les RH vérifient chaque pièce.",
  "HR already has it": "Les RH l'ont déjà",
  "Send a file": "Envoyer un fichier",
  "Save for later": "Enregistrer pour plus tard",
  "This link is personal and works until your first day. Then your account takes over.": "Ce lien est personnel et fonctionne jusqu'à votre premier jour. Votre compte prend ensuite le relais.",
  "Onboarding": "Accueil des nouveaux",
  "Start an onboarding": "Ouvrir un accueil",
  "Welcome page": "Page de bienvenue",
  "From the hire to the end of the trial: the new hire's papers before day one, each step with its owner and date, a buddy, and the manager's trial reviews.": "De l'embauche à la fin de l'essai : les pièces du nouveau avant le premier jour, chaque étape avec son responsable et sa date, un parrain, et les bilans d'essai du responsable.",
  "New hires": "Nouveaux embauchés",
