  "confirmed · {a} ended": "confirmés · {a} rompus",
  "No onboarding open. Hiring a candidate starts one; HR can also start one for anyone hired.": "Aucun accueil en cours. L'embauche d'un candidat en ouvre un ; les RH peuvent aussi en ouvrir un pour toute personne embauchée.",
  "Before day one": "Avant le premier jour",
