  "All done": "Tout est fait",
  "Close this onboarding?": "Clôturer cet accueil ?",
  "The new hire's link stops working. The hiring checklist and the trial reviews stay.": "Le lien du nouveau cesse de fonctionner. La liste d'embauche et les bilans d'essai restent.",
  "Close the onboarding": "Clôturer l'accueil",
  "Starts {d}": "Commence le {d}",
  "Link sent {a}, works until {b}.": "Lien envoyé le {a}, valable jusqu'au {b}.",
  "You can also send it by WhatsApp. Whoever has the link sees the form: send it to the new hire only.": "Vous pouvez aussi l'envoyer par WhatsApp. Quiconque a le lien voit le formulaire : envoyez-le au nouveau seulement.",
  "The new hire gets a link by email to fill in their details and send their papers, with no account.": "Le nouveau reçoit un lien par e-mail pour remplir ses informations et envoyer ses pièces, sans compte.",
  "The start date has passed: the employee fills their file from their account.": "La date d'entrée est passée : l'employé complète son dossier depuis son compte.",
