  "Copied into the employee file on {d}.": "Reporté dans le dossier de l'employé le {d}.",
  "Copy into the employee file?": "Reporter dans le dossier de l'employé ?",
  "What the new hire typed replaces what the file holds; empty answers keep it. Family members are added to the dependants. Check the papers first.": "Ce que le nouveau a saisi remplace ce que contient le dossier ; les réponses vides le laissent tel quel. Les membres de la famille sont ajoutés aux ayants droit. Vérifiez d'abord les pièces.",
  "Copy into the employee file": "Reporter dans le dossier de l'employé",
  "Papers sent": "Pièces envoyées",
  "A colleague who shows the new hire around in the first weeks: the team, the places, the habits. They are told by a notification.": "Un collègue qui guide le nouveau les premières semaines : l'équipe, les lieux, les habitudes. Il est prévenu par une notification.",
  "No buddy": "Pas de parrain",
  "Hiring steps": "Étapes de l'embauche",
  "by {d}": "pour le {d}",
  "Open the full hiring file": "Ouvrir le dossier d'embauche complet",
