  "Refuse {a}": "Refuser : {a}",
  "Why (the new hire reads it)": "Pourquoi (le nouveau le lira)",
  "Blurred photo, expired card…": "Photo floue, carte expirée…",
  "Accept {a}": "Accepter : {a}",
  "Read it on the paper: HR is reminded before it expires.": "Lisez-la sur la pièce : les RH sont prévenus avant l'expiration.",
  "Choose the person.": "Choisissez la personne.",
  "For someone hired without the recruitment pages. Hiring a candidate starts it by itself.": "Pour une personne embauchée sans passer par le recrutement. L'embauche d'un candidat l'ouvre d'elle-même.",
  "Name or matricule": "Nom ou matricule",
  "What every new hire reads on their first day, under their manager, buddy and first steps: where to go, the hours, the rules, who to ask. Markdown: ## title, - list.": "Ce que chaque nouveau lit le premier jour, sous son responsable, son parrain et ses premières étapes : où aller, les horaires, le règlement, à qui s'adresser. Markdown : ## titre, - liste.",
  "## Your first day\n- Come at 8:00 to reception, ground floor\n- Bring your ID card\n\n## Good to know\n- Working hours: 8:00 to 16:30\n- The rules of the house are in My documents": "## Votre premier jour\n- Présentez-vous à 8 h à l'accueil, rez-de-chaussée\n- Apportez votre pièce d'identité\n\n## Bon à savoir\n- Horaires : 8 h à 16 h 30\n- Le règlement intérieur est dans Mes documents",
  "One after the first month, one two weeks before the trial ends: there is still time to give the written notice (Labour Code art. 43).": "Un après le premier mois, un deux semaines avant la fin de l'essai : il reste le temps de notifier par écrit (Code du travail, art. 43).",
