  "Every employer trains its workers (Code du travail art. 8). The plan leaves no category of staff out, trains national managers first, and is drawn up with the workers' representatives (Ordonnance 71-055 art. 17-19).": "Tout employeur assure la formation de ses travailleurs (Code du travail art. 8). Le plan n'exclut aucune catégorie du personnel, forme en priorité les cadres nationaux et est établi avec les représentants des travailleurs (Ordonnance 71-055 art. 17-19).",
