  "{a} needs added from objectives and evaluations.": "{a} besoins ajoutés à partir des objectifs et des évaluations.",
  "Drop this need?": "Abandonner ce besoin ?",
  "Drop": "Abandonner",
  "Needs come from requests of employees and managers, from the development needs written on objectives, and from criteria scored below half in evaluations. Accepted needs are tied to a line of the plan, then to a session.": "Les besoins viennent des demandes des employés et des responsables, des besoins de développement notés sur les objectifs et des critères notés sous la moitié dans les évaluations. Les besoins acceptés sont rattachés à une ligne du plan, puis à une session.",
  "Ask HR for training for someone of your team, and give your opinion on what your team asks for. HR decides.": "Demandez aux RH une formation pour une personne de votre équipe et donnez votre avis sur ce que votre équipe demande. Les RH décident.",
