  "A few months after a training, the manager says whether it changed the person's work. It tells HR which courses are worth running again.": "Quelques mois après une formation, le responsable dit si elle a changé le travail de la personne. Les RH savent ainsi quelles formations valent la peine d'être reconduites.",
  "Nothing to answer.": "Rien à répondre.",
