  "Each person against the skills their job needs. Green: reached; amber: one level short; red: more. A level the employee gave but nobody confirmed yet counts as missing.": "Chaque personne face aux compétences que demande son emploi. Vert : atteint ; orange : un niveau en dessous ; rouge : plus. Un niveau donné par l'employé mais pas encore confirmé compte comme manquant.",
