  "Confidential: only HR and the Direction générale see this page, and every visit is recorded. Employees never see their box, their potential or whether they are a successor.": "Confidentiel : seuls les RH et la Direction générale voient cette page, et chaque consultation est enregistrée. Les employés ne voient jamais leur case, leur potentiel ni s'ils sont successeurs.",
